"""Build a protected local review from explicit native-evidence manifests.

This does not render models, embed cache resources into source, or publish a site.
The resulting HTML references local native outputs and must remain private.
"""
import argparse,json,html
from pathlib import Path

def build(manifest,out):
    out.mkdir(parents=True,exist_ok=True)
    data=json.loads(manifest.read_text());payload=json.dumps(data).replace('<','\\u003c')
    page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ASCENT · Asset fidelity workbench</title><style>
:root{color-scheme:dark;font:16px/1.55 system-ui;background:#10151a;color:#e4e5df}body{margin:0 auto;max-width:1540px;padding:36px 28px}h1{font-size:36px;line-height:1.15;max-width:1000px}h2{font-size:25px;margin-top:64px}h3{margin:0 0 8px}p{max-width:1050px;color:#c4c8c8}small,.tag{color:#a7b3b3}.tag{letter-spacing:.12em;text-transform:uppercase;font-size:12px}a{color:#dfc68f}nav{display:flex;flex-wrap:wrap;gap:24px;margin:28px 0;border-block:1px solid #344047;padding:18px 0}.notice{border-left:3px solid #d0b475;padding:10px 20px;background:#1b2329}.card{background:#171e24;border:1px solid #344047;padding:22px;margin:22px 0;border-radius:8px}.toolbar{display:flex;gap:18px;align-items:center;flex-wrap:wrap;margin:16px 0}select,button{font:inherit;background:#27343d;color:#fff;border:1px solid #637078;border-radius:4px;padding:6px 10px}input[type=range]{flex:1;min-width:250px}.triptych{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.triptych figure{margin:0}.triptych img,.wide{width:100%;background:#10151a;border:1px solid #303b42}.triptych figcaption{font-size:14px;padding:8px 0}table{width:100%;border-collapse:collapse}th,td{padding:12px 10px;text-align:left;border-bottom:1px solid #344047}td p{margin:0}code{font-size:13px;overflow-wrap:anywhere}.originals{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.originals .card{margin:0}.originals img{width:100%}summary{cursor:pointer;color:#dfc68f}.muted{color:#96a8ad} @media(max-width:850px){.triptych,.originals{grid-template-columns:1fr}body{padding:24px 14px}}
</style><div class="tag">ASCENT · Private native evidence · revision 239.1</div><h1>Preservation is verified.<br>Independent art remains under review.</h1><p id="intro"></p><div class="notice">No experimental asset has been integrated into the live Tower. Genuine cache imagery and direct reconstruction studies in this review are protected local resources. Numeric overlap is diagnostic, never artistic approval.</div><nav><a href="#static">Static A / B / C</a><a href="#motion">Native animation</a><a href="#heldout">Held-out failures</a><a href="#originals">Original Tower probes</a><a href="#technical">Technical evidence</a></nav><section id="static"><h2>Controlled static comparisons</h2><p>A is the genuine native asset; B is its saved/reopened Blender round trip; C is independently built from owned primitives and explicit descriptors. Camera and lighting remain fixed to A. Select a view and a retained or earlier C study.</p><div id="static-cards"></div></section><section id="motion"><h2>Animation: compatibility and choreography</h2><p id="motion-note"></p><div class="card"><div class="toolbar"><label>Action <select id="action"></select></label><button id="play">Play</button><label id="time"></label><input id="tick" type="range" min="0" value="0"></div><div id="animated" class="triptych"></div></div><div id="motion-sheets"></div></section><section id="heldout"><h2>Generalization: keep the failures visible</h2><p id="protocol"></p><table><thead><tr><th>Reference</th><th>Frozen result</th><th>Five-view overlap</th><th>Finding</th></tr></thead><tbody id="heldout-rows"></tbody></table><div id="dev-cards"></div></section><section id="originals"><h2>Original Tower design probes</h2><p>These are genuinely new designs and technical/art-direction probes. They do not establish completion of the artistic milestones. Standalone owned renders can be published; scenes beside authentic assets remain private. Each shared scene retains native dimensions, one camera and common lighting.</p><div class="originals" id="original-cards"></div></section><section id="technical"><h2>Reproducibility and limitations</h2><div id="facts"></div><details><summary>Evidence identity and source revisions</summary><pre id="identity"></pre></details><p id="limits"></p></section><script>
const D=DATA;const $=x=>document.getElementById(x);$('intro').textContent=D.intro;$('motion-note').textContent=D.motion.note;$('protocol').textContent=D.protocol;$('identity').textContent=JSON.stringify(D.identity,null,2);$('limits').textContent=D.limits;
function el(tag,text,parent){let e=document.createElement(tag);if(text!==null)e.textContent=text;if(parent)parent.append(e);return e}function imagePanel(parent,label,src){let f=el('figure',null,parent);let a=el('a',null,f);a.href=src;a.target='_blank';let im=el('img',null,a);im.src=src;im.loading='lazy';im.alt=label;el('figcaption',label,f)}
function staticCard(c,parent){let card=el('article',null,parent);card.className='card';el('h3',c.title,card);el('p',c.note,card);let bar=el('div',null,card);bar.className='toolbar';let view=el('select',null,bar);for(let v of ['quarter','front','side','rear','gameplay'])el('option',v,view).value=v;let variant=el('select',null,bar);for(let [i,v]of c.candidates.entries())el('option',v.name,variant).value=i;variant.value=c.candidates.length-1;let grid=el('div',null,card);grid.className='triptych';function update(){grid.replaceChildren();let v=view.value;imagePanel(grid,'A · Authentic native',c.a[v]);if(c.b)imagePanel(grid,'B · Saved Blender round trip',c.b[v]);imagePanel(grid,'C · '+c.candidates[+variant.value].name,c.candidates[+variant.value].views[v])}view.onchange=variant.onchange=update;update()}
D.static.forEach(c=>staticCard(c,$('static-cards')));D.development.forEach(c=>staticCard(c,$('dev-cards')));
for(let f of D.facts){let p=el('p',null,$('facts'));el('strong',f.label+' · ',p);el('span',f.value,p)}for(let r of D.heldout){let tr=el('tr',null,$('heldout-rows'));for(let k of ['reference','status','overlap','finding'])el('td',r[k],tr)}
let timer=null;for(let [name,row]of Object.entries(D.motion.actions))el('option',name,$('action')).value=name;function motion(){let row=D.motion.actions[$('action').value];$('tick').max=row.ticks.length-1;$('tick').value=Math.min(+$('tick').value,row.ticks.length-1);let tick=row.ticks[+$('tick').value];$('time').textContent='tick '+tick+' · same native clock';$('animated').replaceChildren();for(let [name,base]of Object.entries(row.columns)){imagePanel($('animated'),name,base.replace('{tick}',String(tick).padStart(4,'0')))}}$('tick').oninput=motion;$('action').onchange=()=>{$('tick').value=0;motion()};$('play').onclick=()=>{if(timer){clearInterval(timer);timer=null;$('play').textContent='Play'}else{timer=setInterval(()=>{$('tick').value=(+$('tick').value+1)%(+$('tick').max+1);motion()},130);$('play').textContent='Pause'}};motion();for(let s of D.motion.sheets){let d=el('details',null,$('motion-sheets'));el('summary',s.label,d);let a=el('a',null,d);a.href=s.url;a.target='_blank';let im=el('img',null,a);im.src=s.url;im.loading='lazy';im.className='wide'}
for(let c of D.originals){let card=el('article',null,$('original-cards'));card.className='card';el('h3',c.title,card);imagePanel(card,'Owned original · native quarter view',c.standalone);el('p',c.brief,card);for(let [label,url]of Object.entries(c.links)){let p=el('p',null,card);let a=el('a',label,p);a.href=url;a.target='_blank'}el('small',c.identity,card)}
</script></html>'''.replace('const D=DATA','const D='+payload)
    (out/'index.html').write_text(page,encoding='utf-8');print('PRIVATE_NATIVE_REVIEW_READY',out/'index.html')
if __name__=='__main__':
    p=argparse.ArgumentParser();p.add_argument('manifest',type=Path);p.add_argument('out',type=Path);a=p.parse_args();build(a.manifest,a.out)
